// Deterministic seed for the Pipewise CRM.
//
// It talks to the database through plain SQL and the table/column names in the "seed contract" (see the A02 ticket),
// not through your Drizzle objects, so it works with whatever schema you design. It seeds the tables and columns that
// exist: the v0 schema from A01 gets orgs/users/companies/contacts, the schema from A02 gets everything.
//
// Same seed in, same content out (names, emails, dates, amounts). Ids are generated by the database (uuidv7), so they differ per run.
import { faker } from '@faker-js/faker'
import pg from 'pg'

export const SCALES = {
  // `test` is what the activity tests run on (a few seconds); `full` is what `npm run db:seed` loads for you.
  test: { contacts: 12_000, companies: 1_200, deals: 4_800 },
  full: { contacts: 50_000, companies: 5_000, deals: 20_000 },
}

export const ORGS = [
  { slug: 'kestrel', name: 'Kestrel Solar', weight: 0.6 },
  { slug: 'acme', name: 'Acme Freight', weight: 0.24 },
  { slug: 'lumen', name: 'Lumen Dental', weight: 0.12 },
  { slug: 'harbor', name: 'Harbor & Finch LLP', weight: 0.04 },
]

export const STAGES = [
  { name: 'Lead', kind: 'open', weight: 4 },
  { name: 'Qualified', kind: 'open', weight: 3 },
  { name: 'Proposal', kind: 'open', weight: 2 },
  { name: 'Negotiation', kind: 'open', weight: 1.5 },
  { name: 'Won', kind: 'won', weight: 1.2 },
  { name: 'Lost', kind: 'lost', weight: 1.3 },
]

const FROM = new Date('2024-01-01T00:00:00Z')
const TO = new Date('2026-10-01T00:00:00Z')
const SEED = 42

const slugify = (text) => text.toLowerCase().replace(/[^a-z0-9]+/g, '.').replace(/^\.|\.$/g, '')

function weightedPicker(items, weightOf) {
  const total = items.reduce((sum, item) => sum + weightOf(item), 0)
  return () => {
    let r = faker.number.float({ min: 0, max: total })
    for (const item of items) {
      r -= weightOf(item)
      if (r < 0) return item
    }
    return items[items.length - 1]
  }
}

async function tableColumns(client, table) {
  const { rows } = await client.query(
    `select column_name, udt_name, data_type, is_nullable = 'YES' as nullable, column_default is not null as has_default
       from information_schema.columns where table_schema = 'public' and table_name = $1`,
    [table],
  )
  if (rows.length === 0) return null
  return new Map(rows.map((r) => [r.column_name, r]))
}

// Inserts column-oriented data with unnest(). Columns the table does not have are skipped; columns the table needs and the
// seed does not provide must be nullable or have a default (that is the contract for extra columns).
async function insertRows(client, table, columns, count, { returning = 'id' } = {}) {
  const known = await tableColumns(client, table)
  const present = Object.keys(columns).filter((name) => known.has(name))
  const missingRequired = [...known.values()].filter((c) => !c.nullable && !c.has_default && !present.includes(c.column_name))
  if (missingRequired.length > 0) {
    throw new Error(
      `seed: table "${table}" has NOT NULL column(s) without a default that the seed does not know: ${missingRequired.map((c) => c.column_name).join(', ')}. ` +
        'Extra columns must be nullable or have a default (see the A02 ticket, "seed contract").',
    )
  }
  const typeOf = (name) => {
    const c = known.get(name)
    return c.data_type === 'USER-DEFINED' ? `"${c.udt_name}"` : c.udt_name
  }
  const out = []
  for (let start = 0; start < count; start += 10_000) {
    const end = Math.min(start + 10_000, count)
    const sql =
      `insert into "${table}" (${present.map((n) => `"${n}"`).join(', ')}) ` +
      `select * from unnest(${present.map((n, i) => `$${i + 1}::${typeOf(n)}[]`).join(', ')}) returning ${returning}`
    const { rows } = await client.query(sql, present.map((n) => columns[n].slice(start, end)))
    out.push(...rows)
  }
  return out
}

export async function seed({ url, scale = 'test', log = () => {} }) {
  const sizes = SCALES[scale]
  if (!sizes) throw new Error(`seed: unknown scale "${scale}" (use ${Object.keys(SCALES).join(' or ')})`)
  faker.seed(SEED)
  const client = new pg.Client({ connectionString: url })
  await client.connect()
  const summary = {}
  try {
    const have = {}
    for (const table of ['orgs', 'users', 'memberships', 'companies', 'contacts', 'stages', 'deals']) have[table] = await tableColumns(client, table)
    for (const required of ['orgs', 'users', 'companies', 'contacts']) {
      if (!have[required]) throw new Error(`seed: table "${required}" does not exist. Run the migrations first (npm run db:migrate).`)
    }
    const existing = Object.keys(have).filter((t) => have[t])
    await client.query(`truncate ${existing.map((t) => `"${t}"`).join(', ')} restart identity cascade`)

    // orgs
    const orgRows = await insertRows(client, 'orgs', { slug: ORGS.map((o) => o.slug), name: ORGS.map((o) => o.name) }, ORGS.length, { returning: 'id, slug' })
    const orgIdBySlug = new Map(orgRows.map((r) => [r.slug, r.id]))
    const orgs = ORGS.map((o) => ({ ...o, id: orgIdBySlug.get(o.slug) }))
    const pickOrg = weightedPicker(orgs, (o) => o.weight)
    summary.orgs = orgs.length

    // users: 1 admin, 2 managers and 9 reps per org, plus one consultant who belongs to two orgs.
    // Passwords are NOT seeded: you register users through your own sign-up (A05) and attach them with `npm run db:grant`.
    const people = []
    for (const org of orgs) {
      people.push({ org, role: 'admin', email: `admin@${org.slug}.test`, name: `${org.name} Admin` })
      for (let i = 1; i <= 2; i++) people.push({ org, role: 'manager', email: `manager${i}@${org.slug}.test`, name: faker.person.fullName() })
      for (let i = 1; i <= 9; i++) people.push({ org, role: 'rep', email: `rep${i}@${org.slug}.test`, name: faker.person.fullName() })
    }
    people.push({ org: orgs[0], role: 'rep', email: 'consultant@pipewise.test', name: 'Casey Consultant', extra: { org: orgs[1], role: 'manager' } })
    const userRows = await insertRows(client, 'users', { email: people.map((p) => p.email), name: people.map((p) => p.name) }, people.length, { returning: 'id, email' })
    const userIdByEmail = new Map(userRows.map((r) => [r.email, r.id]))
    for (const p of people) p.id = userIdByEmail.get(p.email)
    summary.users = people.length
    if (have.memberships) {
      const memberships = people.flatMap((p) => [{ org: p.org, role: p.role, userId: p.id }, ...(p.extra ? [{ org: p.extra.org, role: p.extra.role, userId: p.id }] : [])])
      await insertRows(
        client,
        'memberships',
        { org_id: memberships.map((m) => m.org.id), user_id: memberships.map((m) => m.userId), role: memberships.map((m) => m.role) },
        memberships.length,
        { returning: 'org_id' },
      )
      summary.memberships = memberships.length
    }
    const repsByOrg = new Map(orgs.map((o) => [o.id, people.filter((p) => p.org.id === o.id && p.role === 'rep').map((p) => p.id)]))

    // companies
    const companyOrgs = Array.from({ length: sizes.companies }, () => pickOrg())
    const companyRows = await insertRows(
      client,
      'companies',
      {
        org_id: companyOrgs.map((o) => o.id),
        name: companyOrgs.map(() => faker.company.name()),
        domain: companyOrgs.map(() => faker.internet.domainName()),
        created_at: companyOrgs.map(() => faker.date.between({ from: FROM, to: TO }).toISOString()),
      },
      sizes.companies,
      { returning: 'id, org_id' },
    )
    const companiesByOrg = new Map(orgs.map((o) => [o.id, []]))
    for (const c of companyRows) companiesByOrg.get(c.org_id).push(c.id)
    summary.companies = companyRows.length
    log(`companies: ${companyRows.length}`)

    // contacts
    const contactSeeds = Array.from({ length: sizes.contacts }, (_, i) => {
      const org = pickOrg()
      const first = faker.person.firstName()
      const last = faker.person.lastName()
      const companies = companiesByOrg.get(org.id)
      const reps = repsByOrg.get(org.id)
      const createdAt = faker.date.between({ from: FROM, to: TO }).toISOString()
      return {
        org,
        name: `${first} ${last}`,
        email: `${slugify(first)}.${slugify(last)}.${i.toString(36)}@example.test`,
        companyId: companies.length > 0 && faker.number.float() < 0.8 ? faker.helpers.arrayElement(companies) : null,
        ownerId: faker.number.float() < 0.9 ? faker.helpers.arrayElement(reps) : null,
        phone: faker.phone.number({ style: 'international' }),
        createdAt,
      }
    })
    const contactRows = await insertRows(
      client,
      'contacts',
      {
        org_id: contactSeeds.map((c) => c.org.id),
        company_id: contactSeeds.map((c) => c.companyId),
        owner_id: contactSeeds.map((c) => c.ownerId),
        name: contactSeeds.map((c) => c.name),
        email: contactSeeds.map((c) => c.email),
        phone: contactSeeds.map((c) => c.phone),
        created_at: contactSeeds.map((c) => c.createdAt),
        updated_at: contactSeeds.map((c) => c.createdAt),
      },
      sizes.contacts,
      { returning: 'id, org_id' },
    )
    summary.contacts = contactRows.length
    log(`contacts: ${contactRows.length}`)

    // stages and deals
    if (have.stages) {
      const stageSeeds = orgs.flatMap((org) => STAGES.map((s, i) => ({ org, ...s, position: i + 1 })))
      const stageRows = await insertRows(
        client,
        'stages',
        {
          org_id: stageSeeds.map((s) => s.org.id),
          name: stageSeeds.map((s) => s.name),
          position: stageSeeds.map((s) => s.position),
          kind: stageSeeds.map((s) => s.kind),
        },
        stageSeeds.length,
        { returning: 'id, org_id, name' },
      )
      summary.stages = stageRows.length
      if (have.deals) {
        const stagesByOrg = new Map(orgs.map((o) => [o.id, stageRows.filter((s) => s.org_id === o.id).map((s) => ({ ...s, ...STAGES.find((x) => x.name === s.name) }))]))
        const contactsByOrg = new Map(orgs.map((o) => [o.id, []]))
        contactSeeds.forEach((c, i) => contactsByOrg.get(c.org.id).push({ id: contactRows[i].id, companyId: c.companyId }))
        const dealSeeds = Array.from({ length: sizes.deals }, () => {
          const org = pickOrg()
          const stage = weightedPicker(stagesByOrg.get(org.id), (s) => s.weight)()
          const contact = faker.helpers.arrayElement(contactsByOrg.get(org.id))
          const createdAt = faker.date.between({ from: FROM, to: TO })
          const closedAt = stage.kind === 'open' ? null : new Date(Math.min(createdAt.getTime() + faker.number.int({ min: 3, max: 90 }) * 86_400_000, TO.getTime()))
          return {
            org,
            stageId: stage.id,
            contactId: contact.id,
            companyId: contact.companyId,
            ownerId: faker.helpers.arrayElement(repsByOrg.get(org.id)),
            title: `${faker.commerce.productAdjective()} ${faker.commerce.product()} rollout`,
            valueCents: String(faker.number.int({ min: 50_000, max: 5_000_000 })),
            createdAt: createdAt.toISOString(),
            closedAt: closedAt && closedAt.toISOString(),
          }
        })
        await insertRows(
          client,
          'deals',
          {
            org_id: dealSeeds.map((d) => d.org.id),
            stage_id: dealSeeds.map((d) => d.stageId),
            contact_id: dealSeeds.map((d) => d.contactId),
            company_id: dealSeeds.map((d) => d.companyId),
            owner_id: dealSeeds.map((d) => d.ownerId),
            title: dealSeeds.map((d) => d.title),
            value_cents: dealSeeds.map((d) => d.valueCents),
            currency: dealSeeds.map(() => 'USD'),
            created_at: dealSeeds.map((d) => d.createdAt),
            closed_at: dealSeeds.map((d) => d.closedAt),
          },
          sizes.deals,
          { returning: 'id' },
        )
        summary.deals = dealSeeds.length
        log(`deals: ${dealSeeds.length}`)
      }
    }
    await client.query('analyze')
  } finally {
    await client.end()
  }
  return summary
}
